mapper.select:
SELECT * FROM
        order_refund WHERE deleted=FALSE
        AND refund_no ILIKE CONCAT('%',#{query.keyword},'%')

        AND status=#{query.status}
        AND order_id=#{query.orderId}
        AND return_id=#{query.returnId}
        AND customer_id=#{query.customerId}
        ORDER BY created_at DESC,id DESC
